import { Agent } from 'undici'
import { Connector } from '@servicenow/sdk-api/connector'
import type { LazyCredential } from '@servicenow/sdk-api/credentials'

export const DEFAULT_TIMEOUT_SECONDS = 3600

/**
 * Builds a Connector for any command that may pull the full app package from the
 * instance (download, transform, move-to-app), so a long-running unload doesn't get
 * killed by undici's default inactivity timeout.
 *
 * @param timeoutSeconds bodyTimeout for the download dispatcher, in seconds.
 * Defaults to DEFAULT_TIMEOUT_SECONDS.
 */
export function createLongRunningConnector(
    credential: LazyCredential,
    timeoutSeconds = DEFAULT_TIMEOUT_SECONDS
): Connector {
    const dispatcher = new Agent({ bodyTimeout: timeoutSeconds * 1000 })
    return new Connector(credential, { dispatcher })
}
